head.script:
/*
 * [메리츠] 엑셀 다운로드 시 customFormatter 가 "화면에 그려진 행"에만 적용되는 문제 재현 예제
 *
 * 배경
 *  - WAEA-695 수정으로 tabControl 비활성 탭의 gridView customFormatter 는 해결됨.
 *  - 그러나 동일 그리드 안에서도 virtual scroll 로 아직 그려지지 않은(스크롤해야 보이는) 행은
 *    엑셀 다운로드 시 customFormatter 의 스타일과 반환 데이터가 반영되지 않는다는 보고가 있음.
 *
 * 재현 조건
 *  - 데이터 행 수 >> visibleRowNum 이어야 virtual scroll 이 동작.
 *  - 이 예제는 500 행, visibleRowNum=10 으로 맞춤.
 *  - 페이지 로드 직후 바로 엑셀 다운로드 버튼을 누르면 아래쪽 행은 "한 번도 그려진 적 없는" 상태.
 *
 * 확인 포인트 (다운로드된 xlsx 를 열어서 검증)
 *  1) Status 컬럼 색상 (setCellColor / setCellBackgroundColor)
 *     - 상위 10~20행 (화면에 그려진 행): 색이 적용되어 있어야 정상
 *     - 중간/하단 행 (스크롤해야 보이는 행): 색이 빠져 있다면 버그 재현
 *  2) Marked 컬럼 값 (customFormatter 반환값으로 데이터 포맷 변환)
 *     - 원본 데이터는 빈 문자열 ""
 *     - customFormatter 가 rowIndex 기반으로 "[ROW_###]" 문자열을 반환
 *     - 상위 그려진 행에는 "[ROW_001]" 처럼 들어가고, 하위 미렌더 행에는 빈 문자열 그대로 남아 있다면 버그 재현
 *
 * 비교 절차
 *  1) 페이지 로드 → 스크롤 하지 말고 곧바로 "엑셀 다운로드 (type:1)" 클릭 → 다운로드 파일 확인
 *  2) 그리드를 맨 아래까지 스크롤하여 모든 행이 한 번씩 렌더되게 한 뒤 다시 다운로드 → 파일 비교
 *     - 스크롤 후 파일에서는 색/Marked 가 모든 행에 정상 반영된다면 "렌더 여부가 원인" 확정
 *  3) type:"0" 도 동일하게 두 번 테스트
 */

scwin.onpageload = function() {
    var TOTAL = 500;
    var statusArr = ["OK", "NG", "HOLD"];
    var json = [];
    for (var i = 0; i < TOTAL; i++) {
        var status = statusArr[i % 3];
        json.push({
            ID: "R" + (10000 + i),
            Name: "사용자_" + (i + 1),
            Status: status,
            Amount: (i % 7 === 0) ? 500000 : (1000000 + i * 1000),
            Marked: "",
            rowStatus: "R"
        });
    }
    dataList1.setJSON(json);
};

// Status 컬럼 - 값에 따라 셀 color / backgroundColor 를 설정 (스타일 side effect)
scwin.statusCustomFormatter = function(data, formattedData, rowIndex, colIndex) {
    if (data === "NG") {
        gridView1.setCellColor(rowIndex, "Status", "#ffffff");
        gridView1.setCellBackgroundColor(rowIndex, "Status", "#e74c3c");
    } else if (data === "OK") {
        gridView1.setCellColor(rowIndex, "Status", "#ffffff");
        gridView1.setCellBackgroundColor(rowIndex, "Status", "#27ae60");
    } else if (data === "HOLD") {
        gridView1.setCellColor(rowIndex, "Status", "#000000");
        gridView1.setCellBackgroundColor(rowIndex, "Status", "#f1c40f");
    }
    return formattedData;
};

// Amount 컬럼 - 100만원 미만은 경고색 (스타일 side effect)
scwin.amountCustomFormatter = function(data, formattedData, rowIndex, colIndex) {
    if (Number(data) < 1000000) {
        gridView1.setCellBackgroundColor(rowIndex, "Amount", "#fdecea");
        gridView1.setCellColor(rowIndex, "Amount", "#c0392b");
    }
    return formattedData;
};

// Marked 컬럼 - 반환값을 강제로 변경. 원본은 "" 인데 customFormatter 가 호출되면 "[ROW_###]" 문자열이 들어감.
// 엑셀 파일에서 이 값이 빠져 있는 행 = customFormatter 미호출 행.
scwin.markedCustomFormatter = function(data, formattedData, rowIndex, colIndex) {
    var num = (typeof rowIndex === "number" ? rowIndex : 0) + 1;
    var padded = ("000" + num).slice(-3);
    return "[ROW_" + padded + "]";
};

// [버그 재현] type:"0" 단독 다운로드
//   - type:0 은 _getExcelRealData 경로로 흘러 엑셀 export 중에는 customFormatter 가 호출되지 않음.
//   - 화면에 이미 렌더된 행은 페이지 로드 당시 setInnerHTML → customFormatter 가 실행되며
//     cellStyleArr 에 스타일이 기록되어 있어 엑셀에 반영됨.
//   - virtual scroll 로 아직 한 번도 그려지지 않은 행은 cellStyleArr 이 비어 있어 엑셀에 스타일이 빠짐.
scwin.trigger_excelType0_onclick = function() {
    var options = {
        fileName: "meritz_customFormatter_type0.xlsx",
        type: "0",
        useStyle: "true",
        setFontSize: "true",
        rowsByN: "10000"
    };
    gridView1.advancedExcelDownload(options);
};

// [비교용] type:"1" 다운로드 (_getExcelDisplayData 경로이므로 전 행 customFormatter 호출됨)
scwin.trigger_excelType1_onclick = function() {
    var options = {
        fileName: "meritz_customFormatter_type1.xlsx",
        type: "1",
        useStyle: "true",
        setFontSize: "true",
        rowsByN: "10000"
    };
    gridView1.advancedExcelDownload(options);
};

// 그리드를 맨 끝까지 스크롤 (모든 행을 한 번씩 렌더시키기 위한 비교 테스트용)
scwin.trigger_scrollAll_onclick = function() {
    var total = gridView1.getTotalRow();
    gridView1.moveRow(total - 1);
};

// 그리드를 다시 맨 위로
scwin.trigger_scrollTop_onclick = function() {
    gridView1.moveRow(0);
};
